// ✅ Safe unwrapping with if-let
func greet(name: String?) {
    if let name = name {
        print("Hello, \(name)!")
    } else {
        print("Hello, stranger!")
    }
}

// ✅ Early exit with guard-let
func process(data: Data?) {
    guard let data = data else {
        print("No data to process")
        return
    }
    // 'data' is non-optional from here on
    parse(data)
}

// ❌ Force unwrapping — crashes if nil
let value: String? = nil
print(value!)  // 💥 Fatal error

struct Company {
    var ceo: Person?
}
struct Person {
    var address: Address?
}
struct Address {
    var city: String?
}

let company: Company? = fetchCompany()

// Optional chaining + nil-coalescing
let city = company?.ceo?.address?.city ?? "Unknown"

// Equivalent without chaining (much more verbose):
let city2: String
if let c = company, let ceo = c.ceo,
   let addr = ceo.address, let ct = addr.city {
    city2 = ct
} else {
    city2 = "Unknown"
}

let input: String? = "42"

// map — transform the wrapped value
let number: Int? = input.map { Int($0) ?? 0 }
// number is Optional(42)

// flatMap — when the transform also returns optional
let parsed: Int? = input.flatMap { Int($0) }
// parsed is Optional(42)

let bad: String? = "hello"
let parsedBad: Int? = bad.flatMap { Int($0) }
// parsedBad is nil — Int("hello") returns nil

// Chaining transforms
let result = input
    .flatMap { Int($0) }
    .map { $0 * 2 }
// result is Optional(84)
